package com.academy.mudogroupware.global.presentation.security;
import com.academy.mudogroupware.global.domain.auth.AuthException; import com.academy.mudogroupware.global.infrastructure.security.jwt.JwtTokenProvider; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpHeaders; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.util.StringUtils; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component @RequiredArgsConstructor public class JwtAuthenticationFilter extends OncePerRequestFilter { private static final String PREFIX="Bearer "; private final JwtTokenProvider provider; private final JwtAuthenticationConverter converter;
 protected void doFilterInternal(HttpServletRequest q,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String t=resolve(q);if(StringUtils.hasText(t)){try{SecurityContextHolder.getContext().setAuthentication(converter.toAuthentication(provider.parseAccessToken(t)));}catch(AuthException e){q.setAttribute("authErrorCode",e.getErrorCode());}}c.doFilter(q,s);}
 private String resolve(HttpServletRequest q){String h=q.getHeader(HttpHeaders.AUTHORIZATION);if(StringUtils.hasText(h)&&h.startsWith(PREFIX)){String t=h.substring(PREFIX.length());if(StringUtils.hasText(t)&&!"null".equals(t)&&!"undefined".equals(t))return t;}if(q.getCookies()!=null)for(Cookie c:q.getCookies())if("accessToken".equals(c.getName())&&StringUtils.hasText(c.getValue()))return c.getValue();return null;}
}
